    public virtual object handleOrderBookMessage(WebSocketClient client, object message, object orderbook, object messageHash, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "asks": [
        //             [ '31738.3', '0.05973179', "0", "3" ],
        //             [ '31738.5', '0.11035404', "0", "2" ],
        //             [ '31739.6', '0.01', "0", "1" ],
        //         ],
        //         "bids": [
        //             [ '31738.2', '0.67557666', "0", "9" ],
        //             [ '31738', '0.02466947', "0", "2" ],
        //             [ '31736.3', '0.01705046', "0", "2" ],
        //         ],
        //         "instId": "BTC-USDT",
        //         "ts": "1626537446491"
        //         "checksum": -855196043,
        //         "prevSeqId": 123456,
        //         "seqId": 123457
        //     }
        //
        List<object> asks = this.safeList(message, "asks", new List<object>() {});
        List<object> bids = this.safeList(message, "bids", new List<object>() {});
        object storedAsks = getValue(orderbook, "asks");
        object storedBids = getValue(orderbook, "bids");
        this.handleDeltas(storedAsks, asks);
        this.handleDeltas(storedBids, bids);
        string? marketId = this.safeString(message, "instId");
        string? symbol = this.safeSymbol(marketId, market);
        Int64? seqId = this.safeInteger(message, "seqId");
        Int64? prevSeqId = this.safeInteger(message, "prevSeqId");
        object nonce = getValue(orderbook, "nonce");
        InvalidNonce? error = null;
        if ((prevSeqId != null) && !(prevSeqId == -1) && !isEqual(nonce, prevSeqId))
        {
            error = new InvalidNonce((this.id + " watchOrderBook received invalid nonce"));
        }
        if ((error != null))
        {
            ((IDictionary<string,object>)client.subscriptions).Remove((string)messageHash);
            if ((symbol != null))
            {
                ((IDictionary<string,object>)this.orderbooks).Remove(symbol);
            }
            client.reject(error, messageHash);
            return orderbook;
        }
        Int64? timestamp = this.safeInteger(message, "ts");
        ((IDictionary<string,object>)orderbook)["nonce"] = seqId;
        ((IDictionary<string,object>)orderbook)["timestamp"] = timestamp;
        ((IDictionary<string,object>)orderbook)["datetime"] = this.iso8601(timestamp);
        return orderbook;
    }

